import { Group, Mesh, PlaneGeometry, DirectionalLight, Color, DoubleSide } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'hub-collection-card-1-label';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ---- Card plate (machined-metal PBR, brushed texture) ----
  const CARD_W = 1.4;
  const CARD_H = CARD_W / (512 / 320); // matches atlas rect aspect (~0.875)

  const cardGeo = new PlaneGeometry(CARD_W, CARD_H);
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.5,
    roughness: 0.55,
    side: DoubleSide,
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.name = 'card-plate';
  root.add(cardMesh);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    if (!cardMat) return;
    tex.colorSpace = THREE.SRGBColorSpace;
    cardMat.map = tex;
    cardMat.needsUpdate = true;
  }).catch(() => {});

  // ---- Thin accent underline (engineered gradient detail, <=10% of frame) ----
  const accentGeo = new PlaneGeometry(CARD_W * 0.5, CARD_H * 0.035);
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    metalness: 0.3,
    roughness: 0.5,
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.6,
  });
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -CARD_H * 0.36, 0.001);
  accentMesh.name = 'accent-underline';
  root.add(accentMesh);

  // ---- Node-local rim lighting (metal needs something to reflect) ----
  const rimLight = new DirectionalLight(new Color(colors.paper), 0.7);
  rimLight.position.set(-1.2, 0.8, 1.6);
  root.add(rimLight);

  const accentRim = new DirectionalLight(new Color(colors.accent), 0.35);
  accentRim.position.set(0.6, -0.4, -1.2);
  root.add(accentRim);

  // ---- Headline text: "Collection 2" ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const text = headlineItem?.text ?? 'Collection 2';
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const textNode = ctx.fontAtlas.createText(text, {
    fontSize,
    color: colors.paper,
    align: 'center',
  });
  textNode.position.set(0, 0, 0.01);
  textNode.name = 'headline-text';
  root.add(textNode);

  // ---- Subtle entrance (weighted, non-linear; respects "static composition" post-settle) ----
  root.scale.set(0.98, 0.98, 0.98);
  cardMesh.material.opacity = 1;
  root.traverse((o) => {
    if (o.material) o.material.transparent = false;
  });

  const tl = gsap.timeline();
  tl.fromTo(
    root.scale,
    { x: 0.97, y: 0.97, z: 0.97 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  tl.fromTo(
    root.position,
    { y: root.position.y - 0.15 },
    { y: root.position.y, duration: 0.7, ease: 'power3.out' },
    0
  );

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(root.position);

    cardGeo.dispose();
    accentGeo.dispose();

    if (cardMat.map) cardMat.map.dispose();
    cardMat.dispose();
    accentMat.dispose();

    root.remove(rimLight);
    root.remove(accentRim);

    if (typeof textNode.userData?.cleanup === 'function') {
      textNode.userData.cleanup();
    }

    root.clear();
  };

  return root;
}
